exec k6 run --out experimental-prometheus-rw --out "json=/results/${POD_NAME}.json" - <<'K6_SCRIPT'
import http from 'k6/http';
import exec from 'k6/execution';
import { check, sleep } from 'k6';

const profiles = {
  "smoke": {
    "deadline": 90,
    "scenario": {
      "executor": "per-vu-iterations",
      "vus": 1,
      "iterations": 10,
      "maxDuration": "1m"
    }
  }
};
const profile = __ENV.K6_PROFILE;
const testid = __ENV.POD_NAME;
if (!Object.prototype.hasOwnProperty.call(profiles, profile)) {
  throw new Error('K6_PROFILE harus memilih salah satu profil yang disediakan.');
}
if (!/^[a-z0-9][a-z0-9-]*$/.test(testid || '')) {
  throw new Error('POD_NAME harus berisi identitas pod untuk testid.');
}

const smoke = profile === 'smoke';
const routes = [
  { name: 'FE_homepage', url: 'http://ecommerce-frontend/', html: true },
  { name: 'BE_products_via_FE', url: 'http://ecommerce-frontend/api/products' },
  { name: 'BE_products_direct', url: 'http://backend:3000/api/products' },
];
// One request per iteration, with a stable 20/60/20 traffic split.
const routeOrder = [0, 1, 2, 1, 1, 0, 1, 2, 1, 1];

const thresholds = {
  checks: [smoke ? 'rate==1' : 'rate>=0.99'],
};
for (const route of routes) {
  const filter = `{name:${route.name}}`;
  thresholds[`http_reqs${filter}`] = ['count>0'];
  thresholds[`http_req_duration${filter}`] = ['p(95)<1000'];
  thresholds[`http_req_failed${filter}`] = smoke ? ['rate==0'] : [
    'rate<0.01',
    { threshold: 'rate<0.20', abortOnFail: true, delayAbortEval: '15s' },
  ];
}
if (!smoke) {
  thresholds.dropped_iterations = [
    'count==0',
    { threshold: 'count<10', abortOnFail: true, delayAbortEval: '15s' },
  ];
}

export const options = {
  systemTags: ['name'],
  tags: { testid },
  scenarios: { capacity: { ...profiles[profile].scenario, gracefulStop: '5s' } },
  thresholds,
};

http.setResponseCallback(http.expectedStatuses(200));

function validResponse(response, route) {
  if (response.status !== 200) return false;
  const contentType = response.headers['Content-Type'] || '';
  if (route.html) {
    return /text\/html/i.test(contentType) && /<html[\s>]/i.test(response.body || '');
  }
  if (!/application\/json/i.test(contentType)) return false;
  try {
    const products = response.json();
    return Array.isArray(products) && products.length > 0;
  } catch (_) {
    return false;
  }
}

export default function () {
  const route = routes[routeOrder[exec.scenario.iterationInTest % routeOrder.length]];
  const response = http.get(route.url, { timeout: '4s', redirects: 0, tags: { name: route.name } });
  check(response, { 'valid response': (r) => validResponse(r, route) }, { name: route.name });
  if (smoke) sleep(1);
}

export function handleSummary(data) {
  const summary = { profile, testid, scenario: options.scenarios.capacity, ...data };
  const failed = Object.entries(data.metrics).flatMap(([metric, value]) =>
    Object.entries(value.thresholds || {}).filter(([, result]) => !result.ok)
      .map(([threshold]) => `${metric}: ${threshold}`));
  return {
    stdout: JSON.stringify({ profile, testid, failedThresholds: failed }) + '\n',
    [`/results/${testid}-summary.json`]: JSON.stringify(summary, null, 2) + '\n',
  };
}
K6_SCRIPT
